"use strict";export function estimateWaitSeconds({queuepos,ownqueued,ownstarted=[],runnerstatus}){if(queuepos==null||runnerstatus==null||runnerstatus.stale||runnerstatus.maintenance){return null}if(ownqueued==null){return null}const runtimes=runnerstatus.typical_runtime_seconds;const numslots=runnerstatus.numslots;const queuedusers=runnerstatus.distinct_queued_users;if(!(numslots>0)||queuedusers==null){return null}const ownslots=Math.min(numslots,Math.max(1,runnerstatus.max_user_slots??1));const concurrency=Math.min(numslots,Math.max(1,queuedusers)*ownslots);const ownahead=ownqueued.filter(task=>task.position<queuepos);const otherahead=Math.max(0,queuepos-ownahead.length);const owntotal=sumOfMedians(ownahead.map(task=>task.requesttype),runtimes);if(owntotal==null){return null}const ownpasses=Math.floor((ownahead.length+ownstarted.length)/ownslots);let ownseconds=0;if(ownpasses>0){const startedtotal=sumOfMedians(ownstarted,runtimes);if(startedtotal==null){return null}ownseconds=ownpasses*(owntotal+startedtotal)/(ownahead.length+ownstarted.length)}let otherseconds=0;const otherpasses=Math.floor(otherahead/concurrency);if(otherpasses>0){const price=meanQueuedRuntimeSeconds(runnerstatus.queued_by_request_type,runtimes);if(price==null){return null}otherseconds=otherpasses*price}return Math.max(ownseconds,otherseconds)}function sumOfMedians(requesttypes,runtimes){let total=0;for(const requesttype of requesttypes){const median=runtimes?.[requesttype];if(!(median>0)){return null}total+=median}return total}function meanQueuedRuntimeSeconds(queuedbytype,runtimes){if(queuedbytype==null){return null}let tasks=0;let seconds=0;for(const[requesttype,count]of Object.entries(queuedbytype)){const median=runtimes?.[requesttype];if(!(count>0)||!(median>0)){continue}tasks+=count;seconds+=count*median}return tasks>0?seconds/tasks:null}export function formatWaitEstimate(seconds){if(seconds==null||!Number.isFinite(seconds)){return null}if(seconds<60){return"under a minute"}if(seconds<90*60){return"~"+Math.ceil(seconds/60)+" min"}if(seconds>=4*60*60){return"over 4 hours"}return"~"+Math.ceil(seconds/3600)+" hours"}export function formatDuration(seconds){if(seconds==null||!Number.isFinite(seconds)||seconds<0){return null}const whole=Math.round(seconds);if(whole<60){return whole+"s"}if(whole<3600){return Math.floor(whole/60)+"m "+String(whole%60).padStart(2,"0")+"s"}return Math.floor(whole/3600)+"h "+String(Math.floor(whole%3600/60)).padStart(2,"0")+"m"}
